/** Generated by scripts/arithmetic.ts from what Typst gives for each pair of kinds. */
import { describe, it } from 'vitest'
import { add, div, minus, times, type Expr, type Value } from '../src/index.ts'

/** The result's type includes the kind Typst gives. */
const covers = <K extends string>(_: Expr<K>, _kind: NoInfer<K>) => {}
declare const i: Value<'int'>, f: Value<'float'>, dec: Value<'decimal'>, len: Value<'length'>, rat: Value<'ratio'>
declare const rel: Value<'relative'>, fra: Value<'fraction'>, ang: Value<'angle'>, dur: Value<'duration'>
declare const dt: Value<'datetime'>, s: Value<'str'>, c: Value<'content'>, arr: Value<'array'>, col: Value<'color'>
declare const byt: Value<'bytes'>, args: Value<'arguments'>

describe('arithmetic', () => {
  it('add', () => {
    covers(add(i, i), 'int') // int + int
    covers(add(i, f), 'float') // int + float
    covers(add(i, 2), 'int') // int + intLiteral
    covers(add(i, 2.5), 'float') // int + floatLiteral
    covers(add(i, dec), 'decimal') // int + decimal
    covers(add(f, i), 'float') // float + int
    covers(add(f, f), 'float') // float + float
    covers(add(f, 2), 'float') // float + intLiteral
    covers(add(f, 2.5), 'float') // float + floatLiteral
    covers(add(2, i), 'int') // intLiteral + int
    covers(add(2, f), 'float') // intLiteral + float
    covers(add(2, 2), 'int') // intLiteral + intLiteral
    covers(add(2, 2.5), 'float') // intLiteral + floatLiteral
    covers(add(2, dec), 'decimal') // intLiteral + decimal
    covers(add(2.5, i), 'float') // floatLiteral + int
    covers(add(2.5, f), 'float') // floatLiteral + float
    covers(add(2.5, 2), 'float') // floatLiteral + intLiteral
    covers(add(2.5, 2.5), 'float') // floatLiteral + floatLiteral
    covers(add(dec, i), 'decimal') // decimal + int
    covers(add(dec, 2), 'decimal') // decimal + intLiteral
    covers(add(dec, dec), 'decimal') // decimal + decimal
    covers(add(len, len), 'length') // length + length
    covers(add(len, rat), 'relative') // length + ratio
    covers(add(len, rel), 'relative') // length + relative
    covers(add(len, col), 'stroke') // length + color
    covers(add(rat, len), 'relative') // ratio + length
    covers(add(rat, rat), 'ratio') // ratio + ratio
    covers(add(rat, rel), 'relative') // ratio + relative
    covers(add(rel, len), 'relative') // relative + length
    covers(add(rel, rat), 'relative') // relative + ratio
    covers(add(rel, rel), 'relative') // relative + relative
    covers(add(fra, fra), 'fraction') // fraction + fraction
    covers(add(ang, ang), 'angle') // angle + angle
    covers(add(dur, dur), 'duration') // duration + duration
    covers(add(dur, dt), 'datetime') // duration + datetime
    covers(add(dt, dur), 'datetime') // datetime + duration
    covers(add('a', 'a'), 'str') // strLiteral + strLiteral
    covers(add('a', s), 'str') // strLiteral + str
    covers(add('a', c), 'content') // strLiteral + content
    covers(add(s, 'a'), 'str') // str + strLiteral
    covers(add(s, s), 'str') // str + str
    covers(add(s, c), 'content') // str + content
    covers(add(c, 'a'), 'content') // content + strLiteral
    covers(add(c, s), 'content') // content + str
    covers(add(c, c), 'content') // content + content
    covers(add([1], [1]), 'array') // arrayLiteral + arrayLiteral
    covers(add([1], arr), 'array') // arrayLiteral + array
    covers(add(arr, [1]), 'array') // array + arrayLiteral
    covers(add(arr, arr), 'array') // array + array
    covers(add({ a: 1 }, { a: 1 }), 'dictionary') // dictLiteral + dictLiteral
    covers(add(col, len), 'stroke') // color + length
    covers(add(byt, byt), 'bytes') // bytes + bytes
    covers(add(args, args), 'arguments') // arguments + arguments
  })
  it('minus', () => {
    covers(minus(i, i), 'int') // int - int
    covers(minus(i, f), 'float') // int - float
    covers(minus(i, 2), 'int') // int - intLiteral
    covers(minus(i, 2.5), 'float') // int - floatLiteral
    covers(minus(i, dec), 'decimal') // int - decimal
    covers(minus(f, i), 'float') // float - int
    covers(minus(f, f), 'float') // float - float
    covers(minus(f, 2), 'float') // float - intLiteral
    covers(minus(f, 2.5), 'float') // float - floatLiteral
    covers(minus(2, i), 'int') // intLiteral - int
    covers(minus(2, f), 'float') // intLiteral - float
    covers(minus(2, 2), 'int') // intLiteral - intLiteral
    covers(minus(2, 2.5), 'float') // intLiteral - floatLiteral
    covers(minus(2, dec), 'decimal') // intLiteral - decimal
    covers(minus(2.5, i), 'float') // floatLiteral - int
    covers(minus(2.5, f), 'float') // floatLiteral - float
    covers(minus(2.5, 2), 'float') // floatLiteral - intLiteral
    covers(minus(2.5, 2.5), 'float') // floatLiteral - floatLiteral
    covers(minus(dec, i), 'decimal') // decimal - int
    covers(minus(dec, 2), 'decimal') // decimal - intLiteral
    covers(minus(dec, dec), 'decimal') // decimal - decimal
    covers(minus(len, len), 'length') // length - length
    covers(minus(len, rat), 'relative') // length - ratio
    covers(minus(len, rel), 'relative') // length - relative
    covers(minus(rat, len), 'relative') // ratio - length
    covers(minus(rat, rat), 'ratio') // ratio - ratio
    covers(minus(rat, rel), 'relative') // ratio - relative
    covers(minus(rel, len), 'relative') // relative - length
    covers(minus(rel, rat), 'relative') // relative - ratio
    covers(minus(rel, rel), 'relative') // relative - relative
    covers(minus(fra, fra), 'fraction') // fraction - fraction
    covers(minus(ang, ang), 'angle') // angle - angle
    covers(minus(dur, dur), 'duration') // duration - duration
    covers(minus(dt, dur), 'datetime') // datetime - duration
    covers(minus(dt, dt), 'duration') // datetime - datetime
  })
  it('times', () => {
    covers(times(i, i), 'int') // int * int
    covers(times(i, f), 'float') // int * float
    covers(times(i, 2), 'int') // int * intLiteral
    covers(times(i, 2.5), 'float') // int * floatLiteral
    covers(times(i, dec), 'decimal') // int * decimal
    covers(times(i, len), 'length') // int * length
    covers(times(i, rat), 'ratio') // int * ratio
    covers(times(i, rel), 'relative') // int * relative
    covers(times(i, fra), 'fraction') // int * fraction
    covers(times(i, ang), 'angle') // int * angle
    covers(times(i, dur), 'duration') // int * duration
    covers(times(i, 'a'), 'str') // int * strLiteral
    covers(times(i, s), 'str') // int * str
    covers(times(i, c), 'content') // int * content
    covers(times(i, [1]), 'array') // int * arrayLiteral
    covers(times(i, arr), 'array') // int * array
    covers(times(f, i), 'float') // float * int
    covers(times(f, f), 'float') // float * float
    covers(times(f, 2), 'float') // float * intLiteral
    covers(times(f, 2.5), 'float') // float * floatLiteral
    covers(times(f, len), 'length') // float * length
    covers(times(f, rat), 'ratio') // float * ratio
    covers(times(f, rel), 'relative') // float * relative
    covers(times(f, fra), 'fraction') // float * fraction
    covers(times(f, ang), 'angle') // float * angle
    covers(times(f, dur), 'duration') // float * duration
    covers(times(2, i), 'int') // intLiteral * int
    covers(times(2, f), 'float') // intLiteral * float
    covers(times(2, 2), 'int') // intLiteral * intLiteral
    covers(times(2, 2.5), 'float') // intLiteral * floatLiteral
    covers(times(2, dec), 'decimal') // intLiteral * decimal
    covers(times(2, len), 'length') // intLiteral * length
    covers(times(2, rat), 'ratio') // intLiteral * ratio
    covers(times(2, rel), 'relative') // intLiteral * relative
    covers(times(2, fra), 'fraction') // intLiteral * fraction
    covers(times(2, ang), 'angle') // intLiteral * angle
    covers(times(2, dur), 'duration') // intLiteral * duration
    covers(times(2, 'a'), 'str') // intLiteral * strLiteral
    covers(times(2, s), 'str') // intLiteral * str
    covers(times(2, c), 'content') // intLiteral * content
    covers(times(2, [1]), 'array') // intLiteral * arrayLiteral
    covers(times(2, arr), 'array') // intLiteral * array
    covers(times(2.5, i), 'float') // floatLiteral * int
    covers(times(2.5, f), 'float') // floatLiteral * float
    covers(times(2.5, 2), 'float') // floatLiteral * intLiteral
    covers(times(2.5, 2.5), 'float') // floatLiteral * floatLiteral
    covers(times(2.5, len), 'length') // floatLiteral * length
    covers(times(2.5, rat), 'ratio') // floatLiteral * ratio
    covers(times(2.5, rel), 'relative') // floatLiteral * relative
    covers(times(2.5, fra), 'fraction') // floatLiteral * fraction
    covers(times(2.5, ang), 'angle') // floatLiteral * angle
    covers(times(2.5, dur), 'duration') // floatLiteral * duration
    covers(times(dec, i), 'decimal') // decimal * int
    covers(times(dec, 2), 'decimal') // decimal * intLiteral
    covers(times(dec, dec), 'decimal') // decimal * decimal
    covers(times(len, i), 'length') // length * int
    covers(times(len, f), 'length') // length * float
    covers(times(len, 2), 'length') // length * intLiteral
    covers(times(len, 2.5), 'length') // length * floatLiteral
    covers(times(len, rat), 'length') // length * ratio
    covers(times(rat, i), 'ratio') // ratio * int
    covers(times(rat, f), 'ratio') // ratio * float
    covers(times(rat, 2), 'ratio') // ratio * intLiteral
    covers(times(rat, 2.5), 'ratio') // ratio * floatLiteral
    covers(times(rat, len), 'length') // ratio * length
    covers(times(rat, rat), 'ratio') // ratio * ratio
    covers(times(rat, rel), 'relative') // ratio * relative
    covers(times(rat, fra), 'fraction') // ratio * fraction
    covers(times(rat, ang), 'angle') // ratio * angle
    covers(times(rel, i), 'relative') // relative * int
    covers(times(rel, f), 'relative') // relative * float
    covers(times(rel, 2), 'relative') // relative * intLiteral
    covers(times(rel, 2.5), 'relative') // relative * floatLiteral
    covers(times(rel, rat), 'relative') // relative * ratio
    covers(times(fra, i), 'fraction') // fraction * int
    covers(times(fra, f), 'fraction') // fraction * float
    covers(times(fra, 2), 'fraction') // fraction * intLiteral
    covers(times(fra, 2.5), 'fraction') // fraction * floatLiteral
    covers(times(fra, rat), 'fraction') // fraction * ratio
    covers(times(ang, i), 'angle') // angle * int
    covers(times(ang, f), 'angle') // angle * float
    covers(times(ang, 2), 'angle') // angle * intLiteral
    covers(times(ang, 2.5), 'angle') // angle * floatLiteral
    covers(times(ang, rat), 'angle') // angle * ratio
    covers(times(dur, i), 'duration') // duration * int
    covers(times(dur, f), 'duration') // duration * float
    covers(times(dur, 2), 'duration') // duration * intLiteral
    covers(times(dur, 2.5), 'duration') // duration * floatLiteral
    covers(times('a', i), 'str') // strLiteral * int
    covers(times('a', 2), 'str') // strLiteral * intLiteral
    covers(times(s, i), 'str') // str * int
    covers(times(s, 2), 'str') // str * intLiteral
    covers(times(c, i), 'content') // content * int
    covers(times(c, 2), 'content') // content * intLiteral
    covers(times([1], i), 'array') // arrayLiteral * int
    covers(times([1], 2), 'array') // arrayLiteral * intLiteral
    covers(times(arr, i), 'array') // array * int
    covers(times(arr, 2), 'array') // array * intLiteral
  })
  it('div', () => {
    covers(div(i, i), 'float') // int / int
    covers(div(i, f), 'float') // int / float
    covers(div(i, 2), 'float') // int / intLiteral
    covers(div(i, 2.5), 'float') // int / floatLiteral
    covers(div(i, dec), 'decimal') // int / decimal
    covers(div(f, i), 'float') // float / int
    covers(div(f, f), 'float') // float / float
    covers(div(f, 2), 'float') // float / intLiteral
    covers(div(f, 2.5), 'float') // float / floatLiteral
    covers(div(2, i), 'float') // intLiteral / int
    covers(div(2, f), 'float') // intLiteral / float
    covers(div(2, 2), 'float') // intLiteral / intLiteral
    covers(div(2, 2.5), 'float') // intLiteral / floatLiteral
    covers(div(2, dec), 'decimal') // intLiteral / decimal
    covers(div(2.5, i), 'float') // floatLiteral / int
    covers(div(2.5, f), 'float') // floatLiteral / float
    covers(div(2.5, 2), 'float') // floatLiteral / intLiteral
    covers(div(2.5, 2.5), 'float') // floatLiteral / floatLiteral
    covers(div(dec, i), 'decimal') // decimal / int
    covers(div(dec, 2), 'decimal') // decimal / intLiteral
    covers(div(dec, dec), 'decimal') // decimal / decimal
    covers(div(len, i), 'length') // length / int
    covers(div(len, f), 'length') // length / float
    covers(div(len, 2), 'length') // length / intLiteral
    covers(div(len, 2.5), 'length') // length / floatLiteral
    covers(div(len, len), 'float') // length / length
    covers(div(rat, i), 'ratio') // ratio / int
    covers(div(rat, f), 'ratio') // ratio / float
    covers(div(rat, 2), 'ratio') // ratio / intLiteral
    covers(div(rat, 2.5), 'ratio') // ratio / floatLiteral
    covers(div(rat, rat), 'float') // ratio / ratio
    covers(div(rel, i), 'relative') // relative / int
    covers(div(rel, f), 'relative') // relative / float
    covers(div(rel, 2), 'relative') // relative / intLiteral
    covers(div(rel, 2.5), 'relative') // relative / floatLiteral
    covers(div(fra, i), 'fraction') // fraction / int
    covers(div(fra, f), 'fraction') // fraction / float
    covers(div(fra, 2), 'fraction') // fraction / intLiteral
    covers(div(fra, 2.5), 'fraction') // fraction / floatLiteral
    covers(div(fra, fra), 'float') // fraction / fraction
    covers(div(ang, i), 'angle') // angle / int
    covers(div(ang, f), 'angle') // angle / float
    covers(div(ang, 2), 'angle') // angle / intLiteral
    covers(div(ang, 2.5), 'angle') // angle / floatLiteral
    covers(div(ang, ang), 'float') // angle / angle
    covers(div(dur, i), 'duration') // duration / int
    covers(div(dur, f), 'duration') // duration / float
    covers(div(dur, 2), 'duration') // duration / intLiteral
    covers(div(dur, 2.5), 'duration') // duration / floatLiteral
    covers(div(dur, dur), 'float') // duration / duration
  })
})
